Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
Bluetooth: L2CAP: Fix stack-out-of-bounds read in
 l2cap_ecred_conn_req

Syzbot reported a KASAN stack-out-of-bounds read in l2cap_build_cmd()
that is triggered by a malformed Enhanced Credit Based Connection Request.

The vulnerability stems from l2cap_ecred_conn_req(). The function allocates
a local stack buffer (`pdu`) designed to hold a maximum of 5 Source Channel
IDs (SCIDs), totaling 18 bytes. When an attacker sends a request with more
than 5 SCIDs, the function calculates `rsp_len` based on this unvalidated
`cmd_len` before checking if the number of SCIDs exceeds
L2CAP_ECRED_MAX_CID.

If the SCID count is too high, the function correctly jumps to the
`response` label to reject the packet, but `rsp_len` retains the
attacker's oversized value. Consequently, l2cap_send_cmd() is instructed
to read past the end of the 18-byte `pdu` buffer, triggering a
KASAN panic.

Fix this by moving the assignment of `rsp_len` to after the `num_scid`
boundary check. If the packet is rejected, `rsp_len` will safely
remain 0, and the error response will only read the 8-byte base header
from the stack.

Fixes: c28d2bff7044 ("Bluetooth: L2CAP: Fix result of L2CAP_ECRED_CONN_RSP when MTU is too short")
Reported-by: syzbot+b7f3e7d9a596bf6a63e3@syzkaller.appspotmail.com
Closes: https://syzkaller.appspot.com/bug?extid=b7f3e7d9a596bf6a63e3
Tested-by: syzbot+b7f3e7d9a596bf6a63e3@syzkaller.appspotmail.com
Signed-off-by: Minseo Park <jacob.park.9436@gmail.com>
Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>

Here is the root cause:
In l2cap_ecred_conn_req, the local stack buffer pdu is sized for a maximum of 5 SCIDs (18 bytes). The function calculates rsp_len from the unvalidated cmd_len before checking if num_scid exceeds L2CAP_ECRED_MAX_CID. When the check fails, the code jumps to the response label with rsp_len already set to the attacker-controlled oversized value, causing l2cap_send_cmd to read past the end of the pdu buffer, resulting in a stack-out-of-bounds read.

Here is the patch:

 static inline int l2cap_ecred_conn_req(struct l2cap_conn *conn,
 				       struct l2cap_cmd_hdr *cmd, u16 cmd_len,
 				       u8 *data)
 {
 	struct l2cap_ecred_conn_req *req = (void *) data;
 	DEFINE_RAW_FLEX(struct l2cap_ecred_conn_rsp, pdu, dcid, L2CAP_ECRED_MAX_CID);
 	struct l2cap_chan *chan, *pchan;
 	u16 mtu, mps;
 	__le16 psm;
 	u8 result, rsp_len = 0;
 	int i, num_scid = 0;
 	bool defer = false;

 	if (!enable_ecred)
 		return -EINVAL;

 	memset(pdu, 0, sizeof(*pdu));

 	if (cmd_len < sizeof(*req) || (cmd_len - sizeof(*req)) % sizeof(u16)) {
 		result = L2CAP_CR_LE_INVALID_PARAMS;
 		goto response;
 	}

 	/* Check if there are no pending channels with the same ident */
 	__l2cap_chan_list_id(conn, cmd->ident, l2cap_ecred_list_defer,
 			     &num_scid);
 	if (num_scid) {
 		result = L2CAP_CR_LE_INVALID_PARAMS;
 		goto response;
 	}

 	cmd_len -= sizeof(*req);
 	num_scid = cmd_len / sizeof(u16);

-	/* Always respond with the same number of scids as in the request */
-	rsp_len = cmd_len;
-
 	if (num_scid > L2CAP_ECRED_MAX_CID) {
 		result = L2CAP_CR_LE_INVALID_PARAMS;
 		goto response;
 	}

+	/* Always respond with the same number of scids as in the request */
+	rsp_len = cmd_len;
+
 	mtu  = __le16_to_cpu(req->mtu);
 	mps  = __le16_to_cpu(req->mps);

 	if (mtu < L2CAP_ECRED_MIN_MTU || mps < L2CAP_ECRED_MIN_MPS) {
 		result = L2CAP_CR_LE_INVALID_PARAMS;
 		goto response;
 	}

 	psm  = req->psm;

 	/* BLUETOOTH CORE SPECIFICATION Version 5.3 | Vol 3, Part A
 	 * page 1059:
 	 *
 	 * Valid range: 0x0001-0x00ff
 	 *
 	 * Table 4.15: L2CAP_LE_CREDIT_BASED_CONNECTION_REQ SPSM ranges
 	 */
 	if (!psm || __le16_to_cpu(psm) > L2CAP_PSM_LE_DYN_END) {
 		result = L2CAP_CR_LE_BAD_PSM;
 		goto response;
 	}

 	BT_DBG("psm 0x%2.2x mtu %u mps %u", __le16_to_cpu(psm), mtu, mps);

 	/* Check if we have socket listening on psm */
 	pchan = l2cap_global_chan_by_psm(BT_LISTEN, psm, &conn->hcon->src,
 					 &conn->hcon->dst, LE_LINK);
 	if (!pchan) {
 		result = L2CAP_CR_LE_BAD_PSM;
 		goto response;
 	}

 	l2cap_chan_lock(pchan);

 	if (!smp_sufficient_security(conn->hcon, pchan->sec_level,
 				     SMP_ALLOW_STK)) {
 		result = pchan->sec_level == BT_SECURITY_MEDIUM ?
 			L2CAP_CR_LE_ENCRYPTION : L2CAP_CR_LE_AUTHENTICATION;
 		goto unlock;
 	}

 	/* Check if the listening channel has set an output MTU then the
 	 * requested MTU shall be less than or equal to that value.
 	 */
 	if (pchan->omtu && mtu < pchan->omtu) {
 		result = L2CAP_CR_LE_UNACCEPT_PARAMS;
 		goto unlock;
 	}

 	result = L2CAP_CR_LE_SUCCESS;

 	for (i = 0; i < num_scid; i++) {
 		u16 scid = __le16_to_cpu(req->scid[i]);

 		BT_DBG("scid[%d] 0x%4.4x", i, scid);

 		pdu->dcid[i] = 0x0000;

 		/* Check for valid dynamic CID range */
 		if (scid < L2CAP_CID_DYN_START || scid > L2CAP_CID_LE_DYN_END) {
 			result = L2CAP_CR_LE_INVALID_SCID;
 			continue;
 		}

 		/* Check if we already have channel with that dcid */
 		if (__l2cap_get_chan_by_dcid(conn, scid)) {
 			result = L2CAP_CR_LE_SCID_IN_USE;
 			continue;
 		}

 		chan = pchan->ops->new_connection(pchan);
 		if (!chan) {
 			result = L2CAP_CR_LE_NO_MEM;
 			continue;
 		}

 		bacpy(&chan->src, &conn->hcon->src);
 		bacpy(&chan->dst, &conn->hcon->dst);
 		chan->src_type = bdaddr_src_type(conn->hcon);
 		chan->dst_type = bdaddr_dst_type(conn->hcon);
 		chan->psm  = psm;
 		chan->dcid = scid;
 		chan->omtu = mtu;
 		chan->remote_mps = mps;

 		__l2cap_chan_add(conn, chan);

 		l2cap_ecred_init(chan, __le16_to_cpu(req->credits));

 		/* Init response */
 		if (!pdu->credits) {
 			pdu->mtu = cpu_to_le16(chan->imtu);
 			pdu->mps = cpu_to_le16(chan->mps);
 			pdu->credits = cpu_to_le16(chan->rx_credits);
 		}

 		pdu->dcid[i] = cpu_to_le16(chan->scid);

 		__set_chan_timer(chan, chan->ops->get_sndtimeo(chan));

 		chan->ident = cmd->ident;
 		chan->mode = L2CAP_MODE_EXT_FLOWCTL;

 		if (test_bit(FLAG_DEFER_SETUP, &chan->flags)) {
 			l2cap_state_change(chan, BT_CONNECT2);
 			defer = true;
 			chan->ops->defer(chan);
 		} else {
 			l2cap_chan_ready(chan);
 		}
 	}

 unlock:
 	l2cap_chan_unlock(pchan);
 	l2cap_chan_put(pchan);

 response:
 	pdu->result = cpu_to_le16(result);

 	if (defer)
 		return 0;

 	l2cap_send_cmd(conn, cmd->ident, L2CAP_ECRED_CONN_RSP,
 		       sizeof(*pdu) + rsp_len, pdu);

 	return 0;
 }



